/** One-shot public case reads stay under the current Host, with no login or supplier mutation. */
import { appPath } from '@deepseek-ai/dsh-client-ui-primitives'
/** Bounded public read result; server diagnostics and credentials never enter this face. */
export type ShowcaseResult = { readonly ok: true; readonly payload: unknown }
  | { readonly ok: false; readonly code: string; readonly httpStatus: number }
/**
 * Read one fixed showcase metadata path without retries or request credentials.
 * @param path - Config or list route generated by the showcase controller.
 * @param signal - Complete read deadline and owner lifecycle cancellation.
 * @returns Public payload or a classified read failure.
 */
export async function requestShowcase(path: string, signal: AbortSignal): Promise<ShowcaseResult> {
  if (!/^(?:\/config|(?:\?[^#]*)?)$/u.test(path)) return { ok: false, code: 'SHOWCASE_INVALID_INPUT', httpStatus: 400 }
  try {
    const response = await fetch(appPath('/credits/api/demand-showcases' + path), {
      method: 'GET', credentials: 'same-origin', cache: 'no-store', redirect: 'error', headers: { accept: 'application/json' }, signal,
    })
    const reader = response.body?.getReader()
    if (reader === undefined) throw new Error('SHOWCASE_PROTOCOL_INVALID')
    let size = 0, raw = ''; const decoder = new TextDecoder()
    try {
      for (;;) {
        const row = await reader.read()
        if (row.done) break
        size += row.value.byteLength
        if (size > 16_777_216) throw new Error('SHOWCASE_PROTOCOL_INVALID')
        raw += decoder.decode(row.value, { stream: true })
      }
      raw += decoder.decode()
    } finally {
      await reader.cancel().catch((_cancelFailure: unknown) => { /* The completed read's original outcome remains authoritative. */ })
    }
    if (!response.ok) return { ok: false, code: response.status === 404 ? 'SHOWCASE_NOT_FOUND'
      : response.status === 401 ? 'SHOWCASE_UNAUTHORIZED' : response.status === 403 ? 'SHOWCASE_FORBIDDEN' : 'SHOWCASE_SERVICE_UNAVAILABLE', httpStatus: response.status }
    const value: unknown = JSON.parse(raw)
    if (value === null || typeof value !== 'object' || !('ok' in value)) throw new Error('SHOWCASE_PROTOCOL_INVALID')
    if (value.ok === true && 'payload' in value) return { ok: true, payload: value.payload }
    if (value.ok === false && 'code' in value && typeof value.code === 'string') return {
      ok: false, code: value.code, httpStatus: 'httpStatus' in value && typeof value.httpStatus === 'number' ? value.httpStatus : response.status,
    }
    throw new Error('SHOWCASE_PROTOCOL_INVALID')
  } catch (error: unknown) {
    return { ok: false, code: signal.aborted ? 'SHOWCASE_TIMEOUT' : error instanceof SyntaxError || error instanceof Error
      && error.message === 'SHOWCASE_PROTOCOL_INVALID' ? 'SHOWCASE_PROTOCOL_INVALID' : 'SHOWCASE_NETWORK', httpStatus: 0 }
  }
}
